[BurstCompile]
struct DirectionJob : IJobParallelFor {
    [ReadOnly] public NativeArray<int> integration;
    [WriteOnly] public NativeArray<sbyte> direction;
    public int rows, cols;
    public void Execute(int cell) {                        // каждая клетка — независимо
        sbyte dir = -1;
        int best = integration[cell], r = cell / cols, c = cell % cols;
        if (best != 0 && best != int.MaxValue) {
            best = int.MaxValue;
            if (r > 0 && integration[cell - cols] < best) { best = integration[cell - cols]; dir = 0; }
            if (c < cols - 1 && integration[cell + 1] < best) { best = integration[cell + 1]; dir = 1; }
            if (r < rows - 1 && integration[cell + cols] < best) { best = integration[cell + cols]; dir = 2; }
            if (c > 0 && integration[cell - 1] < best) dir = 3;
        }
        direction[cell] = dir;
    }
}
