// поставить башню, только если спавн не отрезан от выхода
bool TryPlaceTower(int[][] cost, (int r, int c)[] exits, int r, int c, int spawn) {
    int old = cost[r][c];
    cost[r][c] = 0;                                    // башня — стена
    field.Build(cost, exits);
    if (field.Integration[spawn] != int.MaxValue) return true;   // путь есть: ставим
    cost[r][c] = old;                                  // спавн отрезан: отказ
    field.Build(cost, exits);                          // и поле без башни
    return false;
}
